/**
 * The figure a claim shows and totals: its settled due, else the one a statement bound it to (not while it is
 * pending), else its live due
 * at the rate in force on its date and at least the floor in force on its date (a correction has none), rounded as
 * the policy date decides for it; null (n/a) with none.
 */
export function figureOf(c: Claim, rates: readonly RateView[], floor: FloorOn, policyDate: string | null): string | null {
  if (c.settledDue !== null) return c.settledDue;
  if (isBound(c)) return c.statedDue;
  const due = dueOn(c.amount, rateOn(rates, c.date), roundsHalfUp(c, policyDate));
  return due === null || isCorrection(c) ? due : atLeast(due, floor(c.date));
}

/** Whether the claim keeps a figure whatever the rates: a settled or bound one with a figure. */
export function keepsFigure(c: Claim): boolean {
  return c.settledDue !== null || (isBound(c) && c.statedDue !== null);
}

/**
 * Whether a claim is deferred: OPEN and deferred until a date after the sheet's today. Until today reaches that
 * date it counts in no total, is not overdue and cannot be settled; from then on it is an OPEN claim like any other.
 */
export function deferred(c: Claim, today: string | null): boolean {
  return c.status === 'OPEN' && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
}

/** Whether a claim is overdue: open (or pending), not deferred, and due by a date before the sheet's today. */
export function overdue(c: Claim, today: string | null): boolean {
  return isOpen(c) && today !== null && !deferred(c, today) && c.dueBy < today;
}

/** The floor in force on a date. */
export type FloorOn = (date: string) => string;

/**
 * What the late charge follows: the sheet's today and the late percent in force on a claim's date; and the policy
 * date in force (the sheet's today when the setting is blank), which decides how a claim's live figures round.
 */
export interface Lateness {
  today: string | null;
  latePct: (date: string) => string;
  policyDate: string | null;
}

/** The whole days from one date (yyyy-mm-dd) to another. */
function daysBetween(from: string, to: string): number {
  const utc = (d: string) => {
    const [y, m, day] = d.split('-').map(Number);
    return Date.UTC(y, m - 1, day);
  };
  return Math.round((utc(to) - utc(from)) / 86_400_000);
}

/**
 * The due a claim shows and totals: its figure, and for an overdue claim the late percent in force on its date of
 * that figure for every full 30 days it is overdue, added on top. The charge is never bound by a statement; a settled claim's
 * due already holds it. A correction gains no late charge.
 */
    }

    /** Whether the person has any hold. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** Puts a hold on the person from the date to the date (null: with no end); the ones already put are kept. */
    public void addHold(LocalDate from, LocalDate to) {
        holds.add(new DatedHold(from, to));
    }

    /**
     * Whether the claim counts toward the person's live totals: one whose status counts, except an open one dated
     * within a hold that no statement binds, and one deferred on the sheet's today.
     */
    public boolean countsLive(Claim claim, LocalDate today) {
        return claim.getStatus().counts() && !claim.isDeferredOn(today)
                && !(claim.getStatus().isOpen() && !claim.isBound()
                && holds.stream().anyMatch(h -> h.covers(claim.getDate())));
    }

    /** The version of the person as stored, raised on each save. */
    public long getVersion() {
        return version;
    }
}
